"""Visible set: which ACL groups a requester may read (resolved from the store on every call)."""
from __future__ import annotations

from .model import VisibleSet


def _active_principal(store, pid):
    if not isinstance(pid, str):
        return None
    p = store.principal(pid)
    if p is None or p["status"] != "active":
        return None
    return p


def _membership_groups(store, principal) -> frozenset[str]:
    """Groups named in the principal's membership rows that exist and belong to the principal's tenant."""
    granted = set()
    for gid in store.membership_rows(principal["id"]):
        g = store.group(gid)
        if g is not None and g["tenant"] == principal["tenant"]:
            granted.add(g["id"])
    return frozenset(granted)


def resolve_visible_set(store, principal_id) -> VisibleSet:
    # DECISION: ADR-007
    # Fail closed: anything unclear resolves to the empty set. Access comes only from membership rows;
    # no role, title or ownership ever adds a group (R2).
    empty = VisibleSet(principal_id, None, frozenset())
    p = _active_principal(store, principal_id)
    if p is None:
        return empty
    if p["kind"] == "person":
        return VisibleSet(principal_id, p["tenant"], _membership_groups(store, p))
    if p["kind"] == "agent":
        # An agent acts for an active person of its own tenant. Its own membership rows only narrow what it may
        # use (owner decision OA-1): visible = person's groups ∩ agent's own groups.
        person = _active_principal(store, p["acts_for"])
        if person is None or person["kind"] != "person" or person["tenant"] != p["tenant"]:
            return empty
        groups = _membership_groups(store, person) & _membership_groups(store, p)
        return VisibleSet(principal_id, p["tenant"], groups)
    return empty
"""Brain: keyed-fact upsert, entity cards, and context assembly for one requester."""
from __future__ import annotations

from factstore.text import tokens

from .access import resolve_visible_set
from .compiler import CardTable, digest_of
from .model import Card, ContextItem, VisibleSet
from .search import bm25_rank, link_entities

MAX_PINNED = 3
DEFAULT_K = 10


def _is_id(value) -> bool:
    return isinstance(value, str)


class Brain:
    def __init__(self, store):
        self.store = store
        self._table = CardTable(store)
        self.rebuild()

    # ------------------------------------------------------------ access
    def visible_set(self, principal_id) -> VisibleSet:
        # DECISION: ADR-007
        # Resolved from the store on every call; nothing about a requester is cached.
        return resolve_visible_set(self.store, principal_id)

    def _entity_in_tenant(self, entity_id, vs: VisibleSet) -> bool:
        if vs.tenant is None or not _is_id(entity_id):
            return False
        entity = self.store.entity(entity_id)
        return entity is not None and entity["tenant"] == vs.tenant

    def _fact_visible(self, fact: dict, vs: VisibleSet) -> bool:
        return fact["acl_group"] in vs.groups and self._entity_in_tenant(fact["entity_id"], vs)

    def _card_live(self, card: Card, vs: VisibleSet) -> bool:
        """Card ACL (R5) and exit check (R11): visible to `vs`, and every fact on it is still a head."""
        # DECISION: ADR-007
        if card.acl_group not in vs.groups or not self._entity_in_tenant(card.entity_id, vs):
            return False
        if not card.fact_ids or digest_of(card.text) != card.digest:
            return False
        for fid in card.fact_ids:
            fact = self.store.fact(fid)
            if (fact is None or fact["superseded_by"] is not None or fact["entity_id"] != card.entity_id
                    or fact["acl_group"] != card.acl_group):
                return False
        return True

    # ------------------------------------------------------------ cards
    def cards(self, entity_id, principal_id) -> tuple[Card, ...]:
        vs = self.visible_set(principal_id)
        if not vs.groups or not self._entity_in_tenant(entity_id, vs):
            return ()
        return tuple(c for c in self._table.cards_of(entity_id) if self._card_live(c, vs))

    def card(self, entity_id, principal_id) -> Card | None:
        found = self.cards(entity_id, principal_id)
        return found[0] if found else None

    def rebuild(self) -> None:
        self._table.rebuild()

    # ------------------------------------------------------------ upsert
    def _as_stored(self, value):
        """`value` as the TEXT columns will hold it (SQLite turns 5 into '5'), so repeats compare equal."""
        if value is None or isinstance(value, (str, bytes)):
            return value
        return self.store.conn.execute("SELECT CAST(? AS TEXT)", (value,)).fetchone()[0]

    def upsert(self, source_system, source_entity_id, attribute, *, entity_id, value, valid_from, source,
               acl_group) -> int:
        # DECISION: ADR-009
        # Path A: keyed upsert with supersession, one transaction. A failure anywhere rolls back the store and
        # the derived card tables together (they share the store's connection).
        store = self.store
        with store.transaction():
            old = store.head(source_system, source_entity_id, attribute)
            if (old is not None and old["value"] == self._as_stored(value)
                    and old["valid_from"] == self._as_stored(valid_from)
                    and old["acl_group"] == self._as_stored(acl_group)
                    and old["entity_id"] == self._as_stored(entity_id)):
                return old["id"]
            new_id = store.insert_fact(source_system=source_system, source_entity_id=source_entity_id,
                                       attribute=attribute, entity_id=entity_id, value=value,
                                       valid_from=valid_from, source=source, acl_group=acl_group)
            touched = {(entity_id, acl_group)}
            if old is not None:
                store.supersede(old["id"], new_id)
                touched.add((old["entity_id"], old["acl_group"]))
                touched.update(self._table.pairs_listing(old["id"]))
            self._table.recompile(touched)
            return new_id

    # ------------------------------------------------------------ assembly
    def assemble(self, request, principal_id, k: int = DEFAULT_K) -> list[ContextItem]:
        # DECISION: ADR-010
        # Pinned cards of linked entities first, then lexical-search notes. Candidates are drawn from what the
        # requester can see; the exit check below re-validates each item against the store before it is returned.
        if not _is_id(request) or isinstance(k, bool) or not isinstance(k, int) or k <= 0:
            return []
        vs = self.visible_set(principal_id)
        if not vs.groups:
            return []
        request_tokens = tokens(request)

        card_candidates: list[Card] = []
        for entity_id in link_entities(self.store, request_tokens, vs.tenant):
            card_candidates.extend(c for c in self._table.cards_of(entity_id) if self._card_live(c, vs))

        note_candidates = bm25_rank(self._visible_active_notes(vs), request_tokens)

        # Exit check (R11): resolve the requester afresh and re-validate each candidate; dropped ones are
        # replaced by the next candidates.
        now = self.visible_set(principal_id)
        items: list[ContextItem] = []
        for card in card_candidates:
            if len(items) >= min(MAX_PINNED, k):
                break
            if self._card_live(card, now):
                items.append(ContextItem("card", card.entity_id, card.text, "card", ()))
        seen: set[str] = set()
        for note_id in note_candidates:
            if len(items) >= k:
                break
            if note_id in seen:
                continue
            seen.add(note_id)
            note = self._note_live(note_id, now)
            if note is not None:
                items.append(ContextItem("note", note["id"], note["text"], "search",
                                         self._annotations(note["id"], now)))
        return items

    def _visible_active_notes(self, vs: VisibleSet) -> list[tuple[str, str]]:
        """(id, text) of active notes in the requester's tenant and visible groups; hidden notes are never read."""
        if vs.tenant is None:
            return []
        rows = self.store.conn.execute(
            "SELECT id, acl_group, text FROM notes WHERE tenant = ? AND state = 'active' ORDER BY id", (vs.tenant,))
        return [(nid, text) for nid, group, text in rows if group in vs.groups]

    def _note_live(self, note_id: str, vs: VisibleSet) -> dict | None:
        note = self.store.note(note_id)
        if (note is None or note["state"] != "active" or vs.tenant is None or note["tenant"] != vs.tenant
                or note["acl_group"] not in vs.groups):
            return None
        return note

    def _annotations(self, note_id: str, vs: VisibleSet) -> tuple[str, ...]:
        # DECISION: ADR-009
        # Forward a stale quoted value to its head, in mention order. The head's date and value are disclosed
        # only if the requester can see the head; otherwise (or if the key was released) the bare notice.
        out = []
        for fact_id in self.store.mentions(note_id):
            quoted = self.store.fact(fact_id)
            if quoted is None or quoted["superseded_by"] is None:
                continue
            head = self.store.head_of(fact_id)
            if head is not None and head["superseded_by"] is None and self._fact_visible(head, vs):
                out.append(f"quoted value superseded on {head['valid_from']}; current value {head['value']}")
            else:
                out.append("quoted value superseded")
        return tuple(out)
"""Card compiler and the derived tables (cd_*) that hold compiled cards."""
from __future__ import annotations

import hashlib
import re

from .model import Card

_DDL = (
    "CREATE TABLE IF NOT EXISTS cd_cards(entity_id TEXT NOT NULL, acl_group TEXT NOT NULL, text TEXT NOT NULL, "
    "digest TEXT NOT NULL, PRIMARY KEY (entity_id, acl_group))",
    "CREATE TABLE IF NOT EXISTS cd_card_facts(entity_id TEXT NOT NULL, acl_group TEXT NOT NULL, "
    "fact_id INTEGER NOT NULL, PRIMARY KEY (entity_id, acl_group, fact_id))",
    "CREATE INDEX IF NOT EXISTS cd_card_facts_fact ON cd_card_facts(fact_id)",
)


def digest_of(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


_LINE_BREAKS = re.compile("[\n\r\x0b\x0c\x1c\x1d\x1e\x85\u2028\u2029]")   # everything str.splitlines() splits on


def _inline(value) -> str:
    """A row field as text that cannot start a new card line (a card has one line per fact)."""
    return _LINE_BREAKS.sub(" ", str(value))


def compile_text(name: str, aliases, facts) -> str:
    # DECISION: ADR-010
    # Cards are compiled in code from rows, never from free text. Same rows -> byte-identical text.
    lines = [f"# {_inline(name)}"]
    aliases = sorted(aliases)
    if aliases:
        lines.append("aliases: " + ", ".join(_inline(a) for a in aliases))
    for f in sorted(facts, key=lambda f: (f["attribute"], f["id"])):
        lines.append(f"{_inline(f['attribute'])}: {_inline(f['value'])} "
                     f"(valid_from {_inline(f['valid_from'])}, source {_inline(f['source'])})")
    return "\n".join(lines)


class CardTable:
    """Reads and writes compiled cards in the store's connection (so they share the store's transaction)."""

    def __init__(self, store):
        self.store = store
        self.conn = store.conn
        with store.transaction():
            for stmt in _DDL:
                self.conn.execute(stmt)

    # ------------------------------------------------------------ compile
    def _write(self, entity_id: str, group: str, name: str, aliases, facts) -> None:
        text = compile_text(name, aliases, facts)
        self.conn.execute("INSERT OR REPLACE INTO cd_cards VALUES (?,?,?,?)",
                          (entity_id, group, text, digest_of(text)))
        self.conn.execute("DELETE FROM cd_card_facts WHERE entity_id = ? AND acl_group = ?", (entity_id, group))
        self.conn.executemany("INSERT INTO cd_card_facts VALUES (?,?,?)",
                              [(entity_id, group, f["id"]) for f in sorted(facts, key=lambda f: f["id"])])

    def _drop(self, entity_id: str, group: str) -> None:
        self.conn.execute("DELETE FROM cd_cards WHERE entity_id = ? AND acl_group = ?", (entity_id, group))
        self.conn.execute("DELETE FROM cd_card_facts WHERE entity_id = ? AND acl_group = ?", (entity_id, group))

    def recompile(self, pairs) -> None:
        """Recompile the given (entity_id, acl_group) cards from the store's current head facts."""
        store = self.store
        with store.transaction():
            for entity_id, group in sorted(set(pairs)):
                entity = store.entity(entity_id)
                facts = [f for f in store.head_facts(entity_id) if f["acl_group"] == group] if entity else []
                if entity is None or not facts:
                    self._drop(entity_id, group)
                else:
                    self._write(entity_id, group, entity["name"], store.aliases(entity_id), facts)

    def rebuild(self) -> None:
        """Recompile every card from the store."""
        store = self.store
        with store.transaction():
            self.conn.execute("DELETE FROM cd_cards")
            self.conn.execute("DELETE FROM cd_card_facts")
            by_pair: dict[tuple[str, str], list[dict]] = {}
            for f in store.head_facts():
                by_pair.setdefault((f["entity_id"], f["acl_group"]), []).append(f)
            for (entity_id, group), facts in sorted(by_pair.items()):
                entity = store.entity(entity_id)
                if entity is not None:
                    self._write(entity_id, group, entity["name"], store.aliases(entity_id), facts)

    # ------------------------------------------------------------ read
    def pairs_listing(self, fact_id: int) -> list[tuple[str, str]]:
        return [(r[0], r[1]) for r in self.conn.execute(
            "SELECT entity_id, acl_group FROM cd_card_facts WHERE fact_id = ?", (fact_id,))]

    def cards_of(self, entity_id: str) -> list[Card]:
        """Every compiled card of an entity (all groups), ordered by acl_group. No access check here."""
        out = []
        for group, text, digest in self.conn.execute(
                "SELECT acl_group, text, digest FROM cd_cards WHERE entity_id = ?", (entity_id,)):
            ids = tuple(sorted(r[0] for r in self.conn.execute(
                "SELECT fact_id FROM cd_card_facts WHERE entity_id = ? AND acl_group = ?", (entity_id, group))))
            out.append(Card(entity_id, group, text, ids, digest))
        out.sort(key=lambda c: c.acl_group)
        return out
"""Value types returned by the cards package."""
from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class VisibleSet:
    principal_id: str
    tenant: str | None
    groups: frozenset[str]


@dataclass(frozen=True)
class Card:
    entity_id: str
    acl_group: str
    text: str
    fact_ids: tuple[int, ...]
    digest: str


@dataclass(frozen=True)
class ContextItem:
    kind: str
    ref: str
    text: str
    reason: str
    annotations: tuple[str, ...] = ()
"""Entity linking (R7) and BM25 ranking (R8, R10)."""
from __future__ import annotations

import math
from collections import Counter

from factstore.text import tokens

K1 = 1.2
B = 0.75


def link_entities(store, request_tokens: list[str], tenant: str) -> list[str]:
    """Entity ids linked from the request, ordered by first match position then id.

    Only entities of `tenant` take part. Matches are chosen longest first (equal length: lower entity id,
    then earlier position); a match that overlaps an already chosen one is not linked from that position.
    """
    matches = []
    for e in store.entities():
        if e["tenant"] != tenant:
            continue
        for name in (e["name"], *store.aliases(e["id"])):
            name_tokens = tokens(name)
            n = len(name_tokens)
            if n == 0:
                continue
            for start in range(len(request_tokens) - n + 1):
                if request_tokens[start:start + n] == name_tokens:
                    matches.append((n, e["id"], start))
    matches.sort(key=lambda m: (-m[0], m[1], m[2]))
    taken = [False] * len(request_tokens)
    first: dict[str, int] = {}
    for n, entity_id, start in matches:
        if any(taken[start:start + n]):
            continue
        for i in range(start, start + n):
            taken[i] = True
        first[entity_id] = min(start, first.get(entity_id, start))
    return sorted(first, key=lambda eid: (first[eid], eid))


def bm25_rank(docs: list[tuple[str, str]], query_tokens: list[str]) -> list[str]:
    """Note ids that match at least one query term, best first (ties: id ascending).

    `docs` must already be restricted to what the requester may see: the statistics (document count, document
    frequencies, average length) are computed over exactly these documents and nothing else.
    """
    terms = sorted(set(query_tokens))
    if not docs or not terms:
        return []
    tf = {nid: Counter(tokens(text)) for nid, text in docs}
    length = {nid: sum(c.values()) for nid, c in tf.items()}
    n_docs = len(docs)
    avgdl = sum(length.values()) / n_docs
    if avgdl == 0:
        return []
    df = {t: sum(1 for c in tf.values() if t in c) for t in terms}
    scored = []
    for nid, counts in tf.items():
        score = 0.0
        for t in terms:                     # fixed term order: identical documents get identical scores
            f = counts.get(t, 0)
            if f == 0:
                continue
            idf = math.log(1.0 + (n_docs - df[t] + 0.5) / (df[t] + 0.5))
            score += idf * f * (K1 + 1.0) / (f + K1 * (1.0 - B + B * length[nid] / avgdl))
        if score > 0.0:
            scored.append((-score, nid))
    scored.sort()
    return [nid for _, nid in scored]

