    def entity(self, eid):
        r = self.conn.execute("SELECT id, tenant, name FROM entities WHERE id = ?", (eid,)).fetchone()
        return None if r is None else dict(zip(("id", "tenant", "name"), r))

    def aliases(self, eid) -> list[str]:
